patterns.template:
# Model
श्रेणी {model_name} {
    परिवर्तनी data = {}
    कर्म get(key) { लौटाओ data.get(key) }
    कर्म set(key, value) { data[key] = value }
}

# View
श्रेणी {view_name} {
    कर्म render(model) {
        # Display model data
    }
}

# Controller
श्रेणी {controller_name} {
    परिवर्तनी model = अपरिभाषित
    परिवर्तनी view = अपरिभाषित
    कर्म __init__(model, view) {
        this.model = model
        this.view = view
    }
    कर्म update(key, value) {
        model.set(key, value)
        view.render(model)
    }
}

# Service: {service_name}
श्रेणी {service_name}Service {
    कर्म handle_request(request) {
        # Process request
        लौटाओ response
    }
    कर्म health_check() {
        लौटाओ {"status": "healthy"}
    }
}

# API Gateway
श्रेणी APIGateway {
    परिवर्तनी services = {}
    कर्म route(path, request) {
        service = services.get(path)
        यदि service {
            लौटाओ service.handle_request(request)
        }
        लौटाओ error(404)
    }
}

# Event Bus
श्रेणी EventBus {
    परिवर्तनी handlers = {}
    कर्म subscribe(event_type, handler) {
        यदि event_type not in handlers {
            handlers[event_type] = []
        }
        handlers[event_type].जोडें(handler)
    }
    कर्म publish(event_type, data) {
        के_लिए handler में handlers.get(event_type, []) {
            handler(data)
        }
    }
}

# Producer
कर्म publish_event(bus, event_type, data) {
    bus.publish(event_type, data)
}

# Consumer
कर्म handle_event(data) {
    # Process event
}

# Presentation Layer
श्रेणी PresentationLayer {
    कर्म handle_input(user_input) {
        result = BusinessLayer.process(user_input)
        लौटाओ format_output(result)
    }
}

# Business Layer
श्रेणी BusinessLayer {
    कर्म process(input) {
        # Business logic
        data = DataAccessLayer.fetch(input)
        लौटाओ transform(data)
    }
}

# Data Access Layer
श्रेणी DataAccessLayer {
    कर्म fetch(query) {
        # Database access
        लौटाओ data
    }
}

# Repository Interface
श्रेणी {entity}Repository {
    कर्म find_by_id(id) {
        लौटाओ db.query(id)
    }
    कर्म find_all() {
        लौटाओ db.query_all()
    }
    कर्म save(entity) {
        db.save(entity)
    }
    कर्म delete(id) {
        db.delete(id)
    }
}

# Command Side
श्रेणी CommandHandler {
    कर्म handle_command(command) {
        # Mutate state
        aggregate.execute(command)
        event_store.save(aggregate.events)
    }
}

# Query Side
श्रेणी QueryHandler {
    कर्म handle_query(query) {
        # Read from read-optimized store
        लौटाओ read_store.query(query)
    }
}
